function deepSeekBand(ms){const d=new Date(ms);if(!Number.isFinite(d.getTime()))return null;const weekend=d>=new Date('2026-08-23T00:00:00Z')&&[0,6].includes(d.getUTCDay());if(weekend)return'off-peak';const h=d.getUTCHours()+d.getUTCMinutes()/60;return(h>=1&&h<4)||(h>=6&&h<10)?'peak':'off-peak';}
